DELETE FROM _fleet_sync_status_owed WHERE item_id=?1 AND target_kind=json_extract(?2,'$.kind') AND submitter_kind=(CASE WHEN json_extract(?2,'$.kind')='statusStream' THEN json_extract(?2,'$.value.sender.kind') WHEN json_extract(?2,'$.kind')='project' THEN 'project' ELSE 'machine' END) AND submitter_id=COALESCE(json_extract(?2,'$.value.sender.value'),json_extract(?2,'$.value.peer'),json_extract(?2,'$.value.project')) AND status_route=?2 -> '$.value.route' AND version=CAST(?3 AS INTEGER);
